presentation_impl::presentation_impl()
{
	this->idl_type = 0;
	this->pres_type = 0;
	this->scope_impl = 0;
	this->misc_impl = 0;
	this->pc = 0;
}

presentation_impl::~presentation_impl()
{
}

void presentation_impl::set_idl_type(const char *type)
{
	this->idl_type = type;
}

