{
	return( this->idl_type );
}

void presentation_impl::set_pres_type(const char *type)
{
	this->pres_type = type;
}

const char *presentation_impl::get_pres_type()
{
	return( this->pres_type );
}

void presentation_impl::set_scope_impl(void (*impl)(cast_scope *scope,
