{
	return( this->scope_impl );
}

void presentation_impl::set_misc_impl(void (*impl)(pres_c_1 *pres, tag_list *))
{
	this->misc_impl = impl;
}

void (*presentation_impl::get_misc_impl())(pres_c_1 *pres, tag_list *)
